// Extract the query from the webhook request
const query = $input.body.query;

// Log the received query
console.log('Received query:', query);

// Return the query for further processing
return {
  query: query,
  timestamp: new Date().toISOString()
};

// Format the results into a nice response
const agentResponse = $input.data;
const sqlResults = $('SQLite').item.json;

// Combine the agent's response with the SQL results
let formattedResponse = '';

if (agentResponse && agentResponse.trim()) {
  formattedResponse = agentResponse;
} else {
  // If no agent response, format the SQL results
  if (sqlResults && Array.isArray(sqlResults) && sqlResults.length > 0) {
    formattedResponse = 'Here are the results:\n\n';

    // Create a table header
    const headers = Object.keys(sqlResults[0]);
    formattedResponse += headers.join(' | ') + '\n';
    formattedResponse += headers.map(() => '---').join(' | ') + '\n';

    // Add table rows
    sqlResults.forEach(row => {
      formattedResponse += Object.values(row).join(' | ') + '\n';
    });
  } else {
    formattedResponse = 'No results found for your query.';
  }
}

// Return the formatted response
return {
  result: formattedResponse
};
